---
/**
 * @title PrevNext
 * @level liftoff
 * @description Themed previous/next documentation links.
 * @category Documentation
 * @hydration none
 * @accessibility
 * - Renders a labelled `<nav>` with genuine anchors and `rel` hints.
 * @keyboard
 * - Native link keyboard behavior.
 * @slots
 * - `default`: Optional custom navigation content (e.g. a richer pager bar)
 *   rendered after any supplied links.
 */

import type { HTMLAttributes } from "astro/types";
import "./docs.css";

type Props = HTMLAttributes<"nav"> & {
  previousHref?: string;
  previousLabel?: string;
  nextHref?: string;
  nextLabel?: string;
};
const {
  previousHref,
  previousLabel = "Previous",
  nextHref,
  nextLabel = "Next",
  // Astro keeps the FIRST duplicate attribute when a static attribute and a
  // spread both provide it, so resolve aria-label before the spread instead
  // of relying on spread order.
  "aria-label": ariaLabel = "Previous and next pages",
  ...attrs
} = Astro.props as Props;

---

<nav data-lsui-prev-next aria-label={ariaLabel} {...attrs}>
  {previousHref && <a href={previousHref} rel="prev">{previousLabel}</a>}
  {nextHref && <a href={nextHref} rel="next">{nextLabel}</a>}
  <slot />
</nav>

/* LightSpeedUI Level 2 — documentation chrome; semantic tokens only. */
@layer lsui {
  @layer components {
    [data-lsui-callout] {
      box-sizing: border-box;
      margin-block: var(--space-md);
      padding: var(--space-md);
      border: var(--border-width) solid var(--color-border-strong);
      border-inline-start: var(--border-width-lg, 3px) solid var(--color-ring);
      border-radius: var(--radius-md);
      background: var(--color-surface);
      color: var(--color-text);
    }

    [data-lsui-callout][data-type="warning"] {
      border-inline-start-color: var(--color-warning, var(--color-ring));
    }

    [data-lsui-callout] p:last-child {
      margin-block-end: 0;
    }

    [data-lsui-docs-sidebar] {
      font-family: var(--font-body);
      font-size: var(--text-sm);
    }

    [data-lsui-docs-sidebar] ul {
      list-style: none;
      padding-inline-start: var(--space-3);
    }

    [data-lsui-docs-sidebar] a {
      display: block;
      min-block-size: var(--target-min-size, 1.5rem);
      padding-block: var(--space-1);
      color: var(--color-text-muted);
    }

    [data-lsui-docs-sidebar] a[aria-current="page"] {
      color: var(--color-text);
      font-weight: var(--weight-medium);
    }

    [data-lsui-prev-next] {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: var(--space-md);
      padding-block: var(--space-lg);
    }

    [data-lsui-prev-next] a {
      min-block-size: var(--target-min-size, 1.5rem);
      color: var(--color-text);
    }
  }
}
